    [TestMethod]
    public void ExpandLabelMatchesEveryRfc8448Section3To5Output()
    {
        foreach ((int section, string secretHex, string label, string contextHex, string outputHex) in Rfc8448ExpandLabels)
        {
            byte[] secret = Hex(secretHex);
            byte[] context = Hex(contextHex);
            byte[] expected = Hex(outputHex);
            byte[] output = new byte[expected.Length];
            TlsHkdf.ExpandLabel(HashAlgorithmName.SHA256, secret, Encoding.ASCII.GetBytes(label), context, output);
            Assert.IsTrue(output.AsSpan().SequenceEqual(expected), "section " + section + " label " + label);
        }
    }

    [TestMethod]
    public void ReplaceWithMessageHashMatchesRfc8448Section5Transcript()
    {
        using var transcript = new TranscriptStore(HashAlgorithmName.SHA256);
        transcript.Append(Hex(Rfc8448HrrMessages[0]));
        transcript.ReplaceWithMessageHash();
        Assert.AreEqual(36, transcript.Length);
        Assert.AreEqual(254, transcript.Bytes[0]);
        Assert.AreEqual(0, transcript.Bytes[1]);
        Assert.AreEqual(0, transcript.Bytes[2]);
        Assert.AreEqual(32, transcript.Bytes[3]);

        transcript.Append(Hex(Rfc8448HrrMessages[1]));
        transcript.Append(Hex(Rfc8448HrrMessages[2]));
        transcript.Append(Hex(Rfc8448HrrMessages[3]));
        Span<byte> hash = stackalloc byte[32];
        transcript.CurrentHash(hash);
        byte[] expected = Hex("8aa8e828ec2f8a884fec95a3139de01c15a3daa7ff5bfc3f4bfcc21b438d7bf8");
        Assert.IsTrue(hash.SequenceEqual(expected));
    }

    private static byte[] Hex(string text)
    {
        if (text.Length == 0)
        {
            return [];
        }

        byte[] bytes = new byte[text.Length / 2];
        for (int i = 0; i < bytes.Length; i++)
        {
            bytes[i] = Convert.ToByte(text.Substring(i * 2, 2), 16);
        }

        return bytes;
    }
